import asyncio, subprocess, time, sys, json
from playwright.async_api import async_playwright
srv = subprocess.Popen([sys.executable, '-m', 'http.server', '8795', '--directory', 'lost-atlas'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL); time.sleep(1)
URL = 'http://localhost:8795/index.html'; R = []
def ok(name, cond, extra=''):
    R.append(bool(cond)); print(('OK   ' if cond else 'FAIL ') + name + (' — ' + str(extra) if extra != '' else ''))
async def main():
    errs = []
    async with async_playwright() as p:
        b = await p.chromium.launch(channel='chrome', args=['--no-sandbox', '--autoplay-policy=no-user-gesture-required'])
        async def fresh(geo=(31.65, -7.96)):
            ctx = await b.new_context(viewport={'width': 390, 'height': 844}, device_scale_factor=2, is_mobile=True, has_touch=True, service_workers='block', geolocation={'latitude': geo[0], 'longitude': geo[1], 'accuracy': 10}, permissions=['geolocation'])
            pg = await ctx.new_page()
            pg.on('pageerror', lambda e: errs.append('PAGEERROR ' + str(e)))
            pg.on('console', lambda m: errs.append(m.text) if m.type == 'error' and 'tile.openstreetmap' not in m.text and 'ERR_' not in m.text else None)
            await pg.goto(URL); await pg.wait_for_timeout(1200); await pg.click('[data-act="intro-go"]'); await pg.wait_for_timeout(300)
            await pg.add_style_tag(content='#cardfx{display:none!important}')
            return ctx, pg
        ctx, pg = await fresh()
        ok('bouton « Commencer une aventure » sur la carte', 'aventure' in (await pg.locator('#sessbtn').inner_text()).lower())
        await pg.screenshot(path='s-carte.png')
        await pg.click('#sessbtn'); await pg.wait_for_timeout(300)
        ok('choix de durée : 1, 2, 3, 4 h et durée personnalisée', await pg.locator('[data-act="sess-dur"]').count() == 5 and await pg.locator('#sess-min').count() == 1)
        await pg.screenshot(path='s-duree.png')
        # budget respecté et plus de contenu quand on a plus de temps
        res = await pg.evaluate("[60, 120, 180, 240, 90].map(d => { const g = Session.generate(d, { seed: 7 }); return { d, n: g.items.length, est: g.est, kinds: [...new Set(g.items.map(i => i.k))], main: (g.items.find(i => i.main) || {}).k, t: g.t, gps: g.gps }; })")
        print('  ', res)
        ok('chaque durée : la proposition tient dans 90 % du temps (le reste pour les imprévus) choisi', all(r['est'] <= r['d'] * 0.9 and r['n'] >= 2 for r in res), [(r['d'], r['est'], r['n']) for r in res])
        ok('plus de temps, plus d\'étapes (1 h < 4 h)', res[0]['n'] < res[3]['n'])
        ok('sans GPS : départ dans le territoire où il reste le plus à vivre, pas de fausse position', all(not r['gps'] for r in res))
        ok('chaque partie contient au moins une rencontre', all('interaction' in r['kinds'] for r in res), [r['kinds'] for r in res])
        ok('mélange quêtes, exploration, rencontres', all(k in res[3]['kinds'] for k in ('quete', 'explo', 'interaction')), res[3]['kinds'])
        ok('2 h ou plus : un donjon devient l\'objectif quand le territoire en a un', any(r['main'] == 'donjon' for r in res[1:4]), [r['main'] for r in res])
        allp = await pg.evaluate("(() => { const out = []; for (const t of Data.territories) for (const d of [60, 240]) { const g = Session.generate(d, { seed: 3, t: t.id }); out.push(g.items.every(i => !i.ll || Array.isArray(i.ll)) && g.items.every(i => i.k !== 'interaction' || !i.place || Data.P[i.place])); } return out; })()")
        ok('6 territoires × 2 durées : tous les lieux proposés existent dans l\'atlas', all(allp))
        coh = await pg.evaluate("(() => { const bad = []; for (const t of Data.territories) for (const d of [60, 120, 240]) for (const seed of [1, 2, 3]) { const g = Session.generate(d, { seed, t: t.id }); const m = g.items.find(i => i.main); if (m && m.tt && m.tt !== g.t) bad.push([t.id, d, seed, m.ref]); if (g.from && Data.P[g.from].t !== g.t && m && m.tt) bad.push(['départ', t.id, g.from]); } return bad; })()")
        ok('l\'objectif et le départ sont toujours dans le territoire annoncé', not coh, coh[:4])
        await pg.click('[data-act="sess-dur"][data-v="120"]'); await pg.wait_for_timeout(300)
        t1 = await pg.locator('#sheet h2').inner_text(); items1 = await pg.locator('.sess-list li').count()
        ok('proposition : titre, étapes, bouton de départ', items1 >= 3 and await pg.locator('[data-act="sess-go"]').count() == 1, (t1, items1))
        ok('les rencontres portent toujours la règle de respect', await pg.locator('.si.k-interaction .si-rule').count() == await pg.locator('.si.k-interaction').count() and await pg.locator('.si.k-interaction').count() >= 1)
        await pg.screenshot(path='s-proposition.png', full_page=False)
        sig1 = await pg.evaluate("Session._draft().items.map(i => i.ref).join()")
        await pg.click('[data-act="sess-reroll"]'); await pg.wait_for_timeout(200)
        ok('« Autre proposition » change la partie', await pg.evaluate("Session._draft().items.map(i => i.ref).join()") != sig1)
        t0 = await pg.evaluate("Session._draft().t"); await pg.click('[data-act="sess-terr"]'); await pg.wait_for_timeout(200)
        ok('« Autre quartier » change de territoire', await pg.evaluate("Session._draft().t") != t0)
        await ctx.close()
        # ---- au cœur de Mouassine, avec GPS ----
        M = (31.6311, -7.9888)
        ctx, pg = await fresh(M)
        await pg.click('#fab-gps'); await pg.wait_for_timeout(1500)
        g = await pg.evaluate("Session.generate(120, { seed: 5 })")
        ok('avec GPS : départ là où est le joueur, territoire déduit', g['gps'] and g['t'] == 't2', (g['gps'], g['t']))
        ok('à Mouassine pour 2 h : objectif = le Dédale de Mouassine', [i for i in g['items'] if i.get('main')][0]['ref'] == 'd-mouassine', [i['ref'] for i in g['items'] if i.get('main')])
        await pg.click('#sessbtn'); await pg.click('[data-act="sess-dur"][data-v="120"]'); await pg.wait_for_timeout(200)
        ok('depuis Mouassine, quelle que soit la proposition : le donjon de Mouassine', await pg.evaluate("Session._draft().items.find(i => i.main).ref") == 'd-mouassine')
        await pg.click('[data-act="sess-go"]'); await pg.wait_for_timeout(500)
        ok('départ : session enregistrée, carte affichée, compteur sur la carte', await pg.evaluate("!!Session.cur()") and await pg.locator('#sessbtn.live').count() == 1 and await pg.evaluate("UI.view") == 'atlas')
        ok('le mode exploration est actif', await pg.evaluate("Explore.isOn()"))
        ok('aucun imprévu dans les premières minutes', await pg.evaluate("Session.tick(null) === null"))
        # progression : rencontre faite à la main
        await pg.click('#sessbtn'); await pg.wait_for_timeout(300); await pg.screenshot(path='s-encours.png')
        n_int = await pg.locator('.si.k-interaction [data-act="sess-did"]').count()
        if n_int:
            await pg.locator('.si.k-interaction [data-act="sess-did"]').first.click(); await pg.wait_for_timeout(200)
        ok('« C\'est fait » sur une rencontre : étape accomplie', n_int == 0 or await pg.evaluate("Session.cur().items.some(i => i.k === 'interaction' && i.at)"), n_int)
        # progression : exploration détectée automatiquement
        ex = await pg.evaluate("(Session.cur().items.find(i => i.k === 'explo') || {}).refs || []")
        if ex:
            await pg.evaluate(f"{json.dumps(ex)}.forEach(id => Game.discover(id, 'gps')); Game.check(); Session.check()"); await pg.wait_for_timeout(200)
            ok('exploration : les lieux révélés cochent l\'étape tout seuls', await pg.evaluate("Session.cur().items.find(i => i.k === 'explo').at > 0"))
        # imprévus forcés
        e1 = await pg.evaluate("Session.tick(AtlasMap.fix(), 'secondaire')")
        ok('imprévu « quête secondaire » : toast et entrée dans le récit', e1 and e1['k'] == 'secondaire', e1 and e1['title'])
        if e1:
            await pg.click('#sh-close') if await pg.locator('#sh-close').is_visible() else None
            await pg.click('#sessbtn'); await pg.wait_for_timeout(200); before = await pg.evaluate("Session.cur().items.length")
            await pg.locator(f'[data-act="sess-add"][data-id="{e1["ref"]}"]').click(); await pg.wait_for_timeout(200)
            ok('« Ajouter » : la quête rejoint l\'aventure', await pg.evaluate("Session.cur().items.length") == before + 1)
        e2 = await pg.evaluate("Session.tick(AtlasMap.fix(), 'lieu')")
        ok('imprévu « un lieu se signale » : un vrai lieu inconnu, distance réelle', e2 and await pg.evaluate(f"!Game.disc('{e2['ref']}') && !!Game.pos('{e2['ref']}')") and ' m' in e2['txt'], e2 and e2['txt'])
        e3 = await pg.evaluate("Session.tick(AtlasMap.fix(), 'temporaire')")
        ok('défi de quinze minutes posé', e3 and e3['until'] - e3['at'] == 15 * 60000)
        xp0 = await pg.evaluate("Game.S.xp.exploration")
        await pg.evaluate(f"Game.discover('{e2['ref']}', 'gps'); Session.check()")
        ok('défi relevé à temps : bonus d\'exploration', await pg.evaluate("Session.cur().ev.find(e => e.k === 'temporaire').res") == 'ok' and await pg.evaluate("Game.S.xp.exploration") >= xp0 + 60)
        await pg.click('#sh-close') if await pg.locator('#sh-close').is_visible() else None
        await pg.click('#sessbtn'); await pg.wait_for_timeout(300); await pg.screenshot(path='s-imprevus.png')
        # reprise après rechargement
        await pg.reload(); await pg.wait_for_timeout(1500)
        ok('rechargement en pleine aventure : elle reprend où elle était', await pg.evaluate("!!Session.cur() && Session.cur().ev.length >= 3") and await pg.locator('#sessbtn.live').count() == 1)
        # fin
        xp1 = await pg.evaluate("Game.totalXP()")
        await pg.click('#sessbtn'); await pg.wait_for_timeout(200); await pg.click('[data-act="sess-end"]'); await pg.wait_for_timeout(500)
        ok('fin : récit de retour affiché', await pg.locator('.sess-stats').count() == 1, await pg.locator('#sheet h2').first.inner_text())
        await pg.screenshot(path='s-retour.png')
        ok('fin : carte « Le premier départ » et expérience gagnées', await pg.evaluate("!!V3.st().cards['c-depart']") and await pg.evaluate("Game.totalXP()") > xp1)
        ok('fin : la session est archivée et la carte reprend son bouton', await pg.evaluate("V3.st().sessions.length === 1 && !Session.cur()") and await pg.locator('#sessbtn.live').count() == 0)
        await pg.evaluate("UI.closeSheet(); document.querySelector('#tabbar [data-v=carnet]').click()"); await pg.wait_for_timeout(300)
        ok('carnet : « Aventures vécues »', await pg.locator('.sess-past .sp').count() == 1)
        print('  bloque :', await pg.evaluate("(() => { const r = document.querySelector('.sess-past .sp').getBoundingClientRect(); const e = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2); return e && (e.id || e.className) + ' | ' + r.y + ' ' + innerHeight; })()"))
        await pg.evaluate("document.querySelector('.sess-past .sp').click()"); await pg.wait_for_timeout(200)
        ok('le récit se rouvre depuis le carnet', await pg.locator('.sess-stats').count() == 1)
        await pg.evaluate("UI.closeSheet(); document.querySelector('#tabbar [data-v=quetes]').click()"); await pg.wait_for_timeout(300)
        ok('onglet Aventures : bandeau de départ en tête', await pg.locator('.sess-banner').count() == 1)
        await pg.screenshot(path='s-aventures.png')
        await ctx.close()
        # ---- partie terminée : il reste toujours une aventure possible ----
        ctx, pg = await fresh()
        save = open('lost-atlas-sauvegarde-complete.json', encoding='utf8').read()
        await pg.evaluate("s => { localStorage.setItem('lostAtlas.save.v1', s); }", save); await pg.reload(); await pg.wait_for_timeout(1500)
        r = await pg.evaluate("[60, 240].map(d => { const g = Session.generate(d, { seed: 2 }); return { n: g.items.length, kinds: [...new Set(g.items.map(i => i.k))] }; })")
        ok('jeu fini à 100 % : l\'aventure propose encore rencontres et dérives', all(x['n'] >= 2 for x in r), r)
        ok('ancienne sauvegarde (sans sessions) chargée sans erreur', await pg.evaluate("Array.isArray(V3.st().sessions)"))
        await ctx.close(); await b.close()
    ok('aucune erreur JavaScript', not errs, errs[:4])
    print(f"\n{sum(R)} / {len(R)} tests réussis")
try: asyncio.run(main())
finally: srv.terminate()
